INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (101, 'D.0002', 'Gangguan Penyapihan Ventilator', 'Gangguan penyapihan ventilator adalah ketidakmampuan beradaptasi dengan pengurangan bantuan ventilator mekanik yang dapat menghambat dan memperlama proses penyapihan.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (101, 'Hipersekresi jalan napas');
