INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (101, 'Hambatan upaya nafas ( misalnya nyeri saat bernapas, kelemahan otot pernapasan, efek sedasi)');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (102, 'D.0003', 'Gangguan Pertukaran Gas', 'Gangguan pertukaran gas adalah kelebihan atau kekurangan oksigenasi dan/atau eliminasi karbondioksida pada membran alveolus-kapiler.', 'aktual', 1);
