INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (103, 'D.0004', 'Gangguan Ventilasi Spontan', 'Gangguan ventilasi spontan adalah penurunan cadangan energi yang mengakibatkan pasien tidak mampu bernapas secara adekuat.', 'aktual', 1);
