INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (105, 'D.0006', 'Risiko Aspirasi', 'Risiko aspirasi adalah adalah risiko mengalami masuknya sekresi gastrointestinal, sekresi orofaring, benda cair atau padat ke dalam saluran trakeobronkhial akibat disfungsi mekanisme protektif saluran napas', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (106, 'D.0007', 'Gangguan Sirkulasi Spontan', 'Gangguan sirkulasi spontan adalah ketidakmampuan untuk mempertahankan sirkulasi yang adekuat untuk menunjang kehidupan.', 'aktual', 1);
