INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (107, 'D.0008', 'Penurunan Curah Jantung', 'Penurunan curah jantung adalah ketidakmampuan jantung memompa darah untuk memenuhi kebutuhan metabolisme tubuh.', 'aktual', 1);
