INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (109, 'D.0010', 'Risiko Gangguan Sirkulasi Spontan', 'Risiko gangguan sirkulasi spontan didefinisikan sebagai risiko mengalami ketidakmampuan untuk mempertahankan sirkulasi yang adekuat untuk menunjang kehidupan.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (110, 'D.0011', 'Risiko Penurunan Curah Jantung', 'Risiko penurunan curah jantung adalah diagnosis keperawatan yang didefinisikan sebagai risiko mengalami pemompaan jantung yang tidak adekuat untuk memenuhi kebutuhan metabolisme tubuh.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (111, 'D.0012', 'Risiko Perdarahan', 'Risiko perdarahan adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami kehilangan darah baik internal (terjadi di dalam tubuh) maupun eksternal (terjadi hingga keluar tubuh).', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (112, 'D.0013', 'Risiko Perfusi Gastrointestinal Tidak Efektif', 'Risiko perfusi gastrointestinal tidak efektif adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan sirkulasi gastrointestinal.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (113, 'D.0014', 'Risiko Perfusi Miokard Tidak Efektif', 'Risiko perfusi miokard tidak efektif adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan sirkulasi arteri koroner yang dapat mengganggu metabolisme miokard.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (114, 'D.0015', 'Risiko Perfusi Perifer Tidak Efektif', 'Risiko perfusi perifer tidak efektif adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan sirkulasi darah pada level kapiler yang dapat mengganggu metabolisme tubuh.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (115, 'D.0016', 'Risiko Perfusi Renal Tidak Efektif', 'Risiko perfusi renal tidak efektif adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan sirkulasi darah ke ginjal.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (116, 'D.0017', 'Risiko Perfusi Serebral Tidak Efektif', 'Risiko perfusi serebral tidak efektif adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan sirkulasi darah ke otak.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (117, 'D.0018', 'Berat Badan Lebih', 'Berat badan lebih adalah diagnosis keperawatan yang didefinisikan sebagai akumulasi lemak berlebih atau abnormal yang tidak sesuai dengan usia dan jenis kelamin.', 'aktual', 1);
