INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (118, 'D.0019', 'Defisit Nutrisi', 'Defisit nutrisi merupakan diagnosis keperawatan yang didefinisikan sebagai asupan nutrisi tidak cukup untuk memenuhi kebutuhan metabolisme', 'aktual', 1);
