INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (127, 'D.0028', 'Menyusui Efektif', 'Menyusui efektif', 'aktual', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (128, 'D.0029', 'Menyusui Tidak Efektif', 'Menyusui tidak efektif', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Ketidakadekuatan suplai ASI');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Hambatan pada neonatus (mis: prematuritas, sumbing)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Anomali payudara ibu (misL puting yang masuk ke dalam)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Ketidakadekuatan refleks oksitosin');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Ketidakadekuatan refleks menghisap bayi');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Payudara bengkak');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Riwayat operasi payudara');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (128, 'Kelahiran kembar');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (129, 'D.0030', 'Obesitas', 'Obesitas merupakan diagnosis keperawatan yang didefinisikan sebagai akumulasi lemak berlebih yang tidak sesuai dengan usia dan jenis kelamin, serta melampaui kondisi berat badan lebih (overweight)', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Kurang aktivitas fisik harian');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Kelebihan konsumsi gula');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Gangguan kebiasaan makan');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Gangguan persepsi makan');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Kelebihan konsumsi alkohol');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Penggunaan energi kurang dari asupan');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Sering mengemil');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Sering memakan makanan berminyak/berlemak');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Faktor keturunan (mis. distribusi jaringan adiposa, pengeluaran energi, aktivitas lipase lipoprotein, sintesis lipid, lipolisis)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Penggunaan makanan formula atau makanan campuran (pada bayi)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Asupan kalsium rendah (pada anak-anak)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Berat badan bertambah cepat (selama masa anak-anak, selama masa bayi, termasuk minggu pertama, 4 bulan pertama, dan tahun pertama)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (129, 'Makanan padat sebagai sumber makanan utama pada usia < 5 bulan.');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (130, 'D.0031', 'Risiko Berat Badan Lebih', 'Risiko Berat badan lebih adalah diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami akumulasi lemak berlebih atau abnormal yang tidak sesuai dengan usia dan jenis kelamin.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (131, 'D.0032', 'Risiko Defisit Nutrisi', 'Risiko defisit nutrisi merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami asupan nutrisi tidak cukup untuk memenuhi kebutuhan metabolisme', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (132, 'D.0032', 'Risiko Disfungsi Motilitas Gastrointestinal', 'Risiko disfungsi motilitas gastrointestinal merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami peningkatan, penurunan, tidak efektifnya aktivitas peristaltik gastrointestinal.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (133, 'D.0034', 'Risiko Hipovolemia', 'Risiko hipovolemia merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan volume cairan intravaskular, interstitial, dan/atau intraselular.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (134, 'D.0035', 'Risiko Ikterik Neonatus', 'Risiko ikterik neonatus merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami kulit dan membran mukosa neonatus menguning setelah 24 jam kelahiran akibat bilirubin tidak terkonjugasi masuk ke dalam sirkulasi.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (135, 'D.0036', 'Risiko Ketidakseimbangan Cairan', 'Risiko ketidakseimbangan cairan merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami penurunan, peningkatan, atau percepatan perpindahan cairan dari intravaskuler, interstitial, atau intraseluler.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (136, 'D.0037', 'Risiko Ketidakseimbangan Elektrolit', 'Risiko ketidakseimbangan elektrolit', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (137, 'D.0038', 'Risiko Ketidakstabilan Kadar Glukosa Darah', 'Risiko ketidakstabilan kadar glukosa darah', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (138, 'D.0039', 'Risiko Syok', 'Risiko syok merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami ketidakcukupan aliran darah ke jaringan tubuh, yang dapat mengakibatkan disfungsi seluler yang mengancam jiwa.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (139, 'D.0040', 'Gangguan Eliminasi Urin', 'Gangguan eliminasi urin merupakan diagnosis keperawatan yang didefinisikan sebagai disfungsi eliminasi urin.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Penurunan kapasitas kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Iritasi kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Penurunan kemampuan menyadari tanda-tanda gangguan kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Efek tindakan medis dan diagnostik (mis. operasi ginjal, operasi saluran kemih, anestesi, dan obat-obatan)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Kelemahan otot pelvis');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Ketidakmampuan mengakses toilet (mis. imobilisasi)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Hambatan lingkungan');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Ketidakmampuan mengkomunikasikan kebutuhan eliminasi');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Outlet kandung kemih tidak lengkap (mis. anomali saluran kemih kongenital)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (139, 'Imaturitas (pada anak usia < 3 tahun)');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (140, 'D.0041', 'Inkontinensia Fekal', 'Inkontinensia fekal merupakan diagnosis keperawatan yang didefinisikan sebagai perubahan kebiasaan buang air besar dari pola normal yang ditandai dengan pengeluaran feses secara involunter (tidak disadari)', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (140, 'mayor', 'subjektif', 'Tidak mampu mengontrol pengeluaran feses', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (140, 'mayor', 'subjektif', 'Tidak mampu menunda defekasi', 2);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (140, 'mayor', 'objektif', 'Feses keluar sedikit-sedikit dan sering', 3);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Kerusakan susunan saraf motorik bawah');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Penurunan tonus otot');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Gangguan kognitif');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Penyalahgunaan laksatif');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Kehilangan fungsi pengendalian sfingter rectum');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Pascaoperasi pullthrough dan penutupan kolostomi');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Ketidakmampuan mencapai kamar kecil');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Diare kronis');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (140, 'Stres berlebihan');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (141, 'D.0042', 'Inkontinensia Urin Berlanjut', 'Inkontinensia urin berlanjut merupakan diagnosis keperawatan yang didefinisikan sebagai pengeluaran urin tidak terkendali dan terus menerus tanpa distensi atau perasaan penuh pada kandung kemih.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (141, 'mayor', 'subjektif', 'Keluarnya urin konstan tanpa distensi', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (141, 'mayor', 'subjektif', 'Nokturia (kencing malam hari) lebih dari 2 kali sepanjang tidur', 2);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Neuropati arkus refleks');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Disfungsi neurologis');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Kerusakan refleks kontraksi detrusor');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Trauma');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Kerusakan medulla spinalis');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (141, 'Kelainan anatomis (mis: fistula)');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (142, 'D.0043', 'Inkontinensia Urin Berlebih', 'Inkontinensia urin berlebih merupakan diagnosis keperawatan yang didefinisikan sebagai kehilangan urin yang tidak terkendali akibat overdistensi kandung kemih.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (142, 'mayor', 'subjektif', 'Residu volume urin setelah berkemih atau keluhan kebocoran sedikit urin', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (142, 'mayor', 'subjektif', 'Nokturia', 2);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (142, 'mayor', 'objektif', 'Kandung kemih distensi (bukan berhubungan dengan penyebab reversible akut) atau kandung kemih distensi dengan sering, sedikit berkemih, atau dribbling.', 3);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (142, 'Blok sfingter');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (142, 'Kerusakan atau ketidakadekuatan jalur aferen');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (142, 'Obstruksi jalan keluar urin (mis: impaksi fekal, efek agen farmakologis)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (142, 'Ketidakadekuatan detrusor (mis: pada konsisi stress atau tidak nyaman, deconditioned voiding)');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (143, 'D.0044', 'Inkontinensia Urin Fungsional', 'Inkontinensia urin fungsional merupakan diagnosis keperawatan yang didefinisikan sebagai pengeluaran urin tidak terkendali karena kesulitan dan tidak mampu mencapai toilet pada waktu yang tepat.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (143, 'mayor', 'subjektif', 'Mengompol sebelum mencapai atau selama usaha mencapai toilet', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (143, 'mayor', 'objektif', 'Tidak tersedia', 2);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Ketidakmampuan atau penurunan mengenali tanda-tanda berkemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Penurunan tonus kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Hambatan mobilisasi');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Faktor psikologis, mis: penurunan perhatian pada tanda-tanda keinginan berkemih (depresi, bingung, delirium).');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Hambatan lingkungan (toilet jauh, tempat tidur terlalu tinggi, lingkungan baru)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Kehilangan sensorik dan motorik (pada geriatri)');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (143, 'Gangguan penglihatan.');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (144, 'D.0045', 'Inkontinensia Urin Refleks', 'Inkontinensia urin refleks merupakan diagnosis keperawatan yang didefinisikan sebagai pengeluaran urin yang tidak terkendali pada saat volume kandung kemih tertentu tercapai.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Tidak mengalami sensasi berkemih', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Dribbling', 2);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Sering buang air kecil', 3);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Hesitancy', 4);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Nokturia', 5);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'subjektif', 'Enuresis', 6);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (144, 'mayor', 'objektif', 'Volume residu urin meningkat', 7);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (144, 'Kerusakan konduksi impuls di atas arkus refleks');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (144, 'Kerusakan jaringan (mis: terapi radiasi).');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (145, 'D.0046', 'Inkontinensia Urin Stres', 'Inkontinensia urin stres merupakan diagnosis keperawatan yang didefinisikan sebagai kebocoran urin mendadak dan tidak dapat dikendalikan karena aktivitas yang meningkatkan tekanan intraabdominal.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (145, 'mayor', 'subjektif', 'Mengeluh keluar urin < 50 ml saat tekanan abdominal meningkat (mis: saat berdiri, bersin, tertawa, berlari, atau mengangkat benda berat)', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (145, 'mayor', 'objektif', 'Tidak tersedia', 2);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (145, 'Kelemahan intrinsik sfingter uretra');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (145, 'Perubahan degenerasi/non degenerasi otot pelvis');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (145, 'Kekurangan estrogen');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (145, 'Peningkatan tekanan intraabdomen');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (145, 'Kelemahan otot pelvis');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (146, 'D.0047', 'Inkontinensia Urin Urgensi', 'Inkontinensia urin urgensi merupakan diagnosis keperawatan yang didefinisikan sebagai keluarnya urin tidak terkendali sesaat setelah keinginan yang kuat untuk berkemih (kebelet).', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (146, 'mayor', 'subjektif', 'Keinginan berkemih yang kuat disertai dengan inkontinensia', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (146, 'mayor', 'objektif', 'Tidak tersedia', 2);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (146, 'Iritasi reseptor kontraksi kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (146, 'Penurunan kapasitas kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (146, 'Hiperaktivitas detrusor dengan kerusakan kontraktilitas kandung kemih');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (146, 'Efek agen farmakologis (mis: diuretik)');
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (147, 'D.0048', 'Kesiapan Peningkatan Eliminasi Urin', 'Kesiapan peningkatan eliminasi urin', 'promosi kesehatan', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (147, 'mayor', 'objektif', 'Jumlah urin normal', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (147, 'mayor', 'objektif', 'Karakteristik urin normal', 2);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (148, 'D.0049', 'Konstipasi', 'Konstipasi merupakan diagnosis keperawatan yang didefinisikan sebagai penurunan defekasi normal yang disertai pengeluaran feses sulit dan tidak tuntas serta feses kering dan banyak.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (148, 'mayor', 'subjektif', 'Defekasi kurang dari 2 kali seminggu', 1);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (148, 'mayor', 'subjektif', 'Pengeluaran feses lama dan sulit', 2);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (148, 'mayor', 'objektif', 'Feses keras', 3);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (148, 'mayor', 'objektif', 'Peristaltik usus menurun', 4);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (148, 'Penurunan motilitas gastrointestinal');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (148, 'Ketidakadekuatan pertumbuhan gigi');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (148, 'Ketidakcukupan diet');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (148, 'Ketidakcukupan asupan serat');
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (148, 'Ketidakcukupan asupan cairan');
