INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (164, 'D.0065', 'Konfusi Kronis', 'Konfusi kronis merupakan diagnosis keperawatan yang didefinisikan sebagai gangguan kesadaran, perhatian, kognitif, dan persepsi yang ireversible, berlangsung lama, dan/atau progresif.', 'aktual', 1);
