INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (167, 'D.0068', 'Risiko Konfusi Akut', 'Risiko konfusi akut merupakan diagnosis keperawatan yang didefinisikan sebagai berisiko mengalami gangguan kesadaran, perhatian, kognisi, dan persepsi yang reversible dan terjadi dalam periode waktu singkat.', 'risiko', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (168, 'D.0069', 'Disfungsi Seksual', 'Disfungsi seksual merupakan diagnosis keperawatan yang didefinisikan sebagai perubahan fungsi seksual selama fase respon seksual berupa hasrat, terangsang, orgasme, dan/atau relaksasi yang dirasa tidak memuaskan, tidak bermakna, atau tidak adekuat.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki_etiologi (id_sdki, deskripsi) VALUES (168, 'Perubahan fungsi/struktur tubuh (mis: kehamilan, baru melahirkan, obat-obatan, pembedahan, anomali, proses penyakit, trauma, radiasi)');
