INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (169, 'D.0070', 'Kesiapan Persalinan', 'Kesiapan persalinan merupakan diagnosis keperawatan yang didefinisikan sebagai pola mempersiapkan, mempertahankan, dan memperkuat proses kehamilan dan persalinan serta perawatan bayi baru lahir.', 'aktual', 1);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (170, 'D.0071', 'Pola Seksual Tidak Efektif', 'Pola seksual tidak efektif merupakan diagnosis keperawatan yang didefinisikan sebagai kekhawatiran individu melakukan hubungan seksual yang berisiko menyebabkan perubahan Kesehatan.', 'aktual', 1);
