INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (188, 'D.0089', 'Kesiapan Peningkatan Konsep Diri', 'Kesiapan peningkatan konsep diri merupakan diagnosis keperawatan yang didefinisikan sebagai pola persepsi diri yang cukup untuk merasa sejahtera dan dapat ditingkatkan.', 'promosi kesehatan', 2);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (189, 'D.0090', 'Kesiapan Peningkatan Koping Keluarga', 'Kesiapan peningkatan koping keluarga merupakan diagnosis keperawatan yang didefinisikan sebagai pola adaptasi anggota keluarga dalam mengatasi situasi yang dialami klien secara efektif dan menunjukkan keinginan serta kesiapan untuk meningkatkan Kesehatan keluarga dan klien.', 'promosi kesehatan', 2);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (190, 'D.0091', 'Kesiapan Peningkatan Koping Komunitas', 'Kesiapan peningkatan koping komunitas merupakan diagnosis keperawatan yang didefinisikan sebagai pola adaptasi dan penyelesaian masalah komunitas yang memuaskan untuk memenuhi tuntutan atau kebutuhan masyarakat, serta dapat ditingkatkan untuk penatalaksanaan masalah saat ini dan mendatang.', 'promosi kesehatan', 2);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (191, 'D.0092', 'Ketidakberdayaan', 'Ketidakberdayaan merupakan diagnosis keperawatan yang didefinisikan sebagai persepsi bahwa tindakan seseorang tidak akan mempengaruhi hasil secara signifikan; persepsi kurang kontrol pada situasi saat ini atau yang akan datang.', 'aktual', 2);
