INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (207, 'D.0109', 'Defisit Perawatan Diri', 'Defisit perawatan diri merupakan diagnosis keperawatan yang didefinisikan sebagai ketidakmampuan melakukan atau menyelesaikan aktivitas perawatan diri.', 'aktual', 3);
