INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (208, 'D.0110', 'Defisit Kesehatan komunitas', 'Defisit kesehatan komunitas merupakan diagnosis keperawatan yang didefinisikan sebagai terdapatnya masalah Kesehatan atau faktor risiko yang dapat mengganggu kesejahteraan pada suatu kelompok.', 'aktual', 2);
