INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (209, 'D.0111', 'Defisit Pengetahuan', 'Defisit pengetahuan merupakan diagnosis keperawatan yang didefinisikan sebagai ketiadaan atau kurangnya informasi kognitif yang berkaitan dengan topik tertentu.', 'aktual', 2);
