INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (210, 'D.0112', 'Kesiapan Peningkatan Manajemen Kesehatan', 'Kesiapan peningkatan manajemen kesehatan merupakan diagnosis keperawatan yang didefinisikan sebagai pola pengaturan dan pengintegrasian program Kesehatan ke dalam kehidupan sehari-hari yang cukup untuk memenuhi tujuan Kesehatan dan dapat ditingkatkan', 'promosi kesehatan', 2);
INSERT IGNORE INTO mst_sdki_tanda_gejala (id_sdki, tipe, kelompok, deskripsi, urutan) VALUES (210, 'mayor', 'subjektif', 'Mengekspresikan keinginan untuk mengelola masalah Kesehatan dan pencegahannya', 1);
