INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (211, 'D.0113', 'Kesiapan Peningkatan Pengetahuan', 'Kesiapan peningkatan pengetahuan merupakan diagnosis keperawatan yang didefinisikan sebagai perkembangan informasi kognitif yang berhubungan dengan topik spesifik cukup untuk memenuhi tujuan Kesehatan dan dapat ditingkatkan.', 'promosi kesehatan', 2);
INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (212, 'D.0114', 'Ketidakpatuhan', 'Ketidakpatuhan merupakan diagnosis keperawatan yang didefinisikan sebagai perilaku individu dan/atau pemberi asuhan tidak mengikuti rencana perawatan/pengobatan yang disepakati dengan tenaga Kesehatan, sehingga menyebabkan hasil perawatan/pengobatan tidak efektif.', 'aktual', 2);
