INSERT IGNORE INTO mst_sdki (id, kode, label, definisi, jenis, id_kategori) VALUES (213, 'D.0115', 'Manajemen Kesehatan Keluarga Tidak Efektif', 'Manajemen kesehatan keluarga tidak efektif merupakan diagnosis keperawatan yang didefinisikan sebagai pola penanganan masalah Kesehatan dalam keluarga tidak memuaskan untuk memulihkan kondisi Kesehatan anggota keluarga.', 'aktual', 2);
