INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Observasi', 'Monitor tanda dan gejala infeksi saluran napas', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Observasi', 'Monitor input dan output cairan (misal: jumlah dan karakteristik)', 4);
