INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Edukasi', 'Anjurkan Tarik napas dalam melalui hidung selama 4 detik, ditahan selama 2 detik, kemudian keluarkan dari mulut dengan bibir mencucu (dibulatkan) selama 8 detik', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Edukasi', 'Anjurkan mengulangi Tarik napas dalam hingga 3 kali', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Edukasi', 'Anjutkan batuk dengan kuat langsung setelah Tarik napas dalam yang ke-3', 4);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (100, 'Kolaborasi', 'Kolaborasi pemberian mukolitik atau ekspektoran, jika perlu.', 1);
INSERT IGNORE INTO mst_siki (id, kode, label, tipe, definisi) VALUES (101, 'I.01011', 'Manajemen Jalan Napas', 'utama', '');
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Observasi', 'Monitor pola napas (frekuensi, kedalaman, usaha napas)', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Observasi', 'Monitor bunyi napas tambahan (misalnya: gurgling, mengi, wheezing, ronchi kering)', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Observasi', 'Monitor sputum (jumlah, warna, aroma)', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Pertahankan kepatenan jalan napas dengan head-tilt dan chin-lift (jaw thrust jika curiga trauma fraktur servikal)', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Posisikan semi-fowler atau fowler', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Berikan minum hangat', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Lakukan fisioterapi dada, jika perlu', 4);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Lakukan penghisapan lendir kurang dari 15 detik', 5);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Lakukan hiperoksigenasi sebelum penghisapan endotrakeal', 6);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Keluarkan sumbatan benda padat dengan forsep McGill', 7);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Terapeutik', 'Berikan oksigen, jika perlu', 8);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Edukasi', 'Anjurkan asupan cairan 2000 ml/hari, jika tidak ada kontraindikasi', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (101, 'Edukasi', 'Ajarkan Teknik batuk efektif', 2);
