INSERT IGNORE INTO mst_siki (id, kode, label, tipe, definisi) VALUES (102, 'I.01014', 'Pemantauan Respirasi', 'utama', '');
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (102, 'Observasi', 'Monitor frekuensi, irama, kedalaman dan upaya napas', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (102, 'Observasi', 'Monitor pola napas (seperti bradypnea, takipnea, hiperventilasi, kussmaul, Cheyne-stokes, biot, ataksik)', 2);
