INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Terapeutik', 'Lakukan pengisapan jalan napas, jika perlu', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Terapeutik', 'Berikan fisioterapi dada, jika perlu', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Terapeutik', 'Lakukan ujicoba penyapihan (30 – 120 menit dengan napas spontan yang dibantu ventilator)', 4);
