INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Terapeutik', 'Hindari pemberian sedasi farmakologis selama percobaan penyapihan', 6);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Terapeutik', 'Berikan dukungan psikologis', 7);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Edukasi', 'Ajarkan cara pengontrolan napas saat penyapihan', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (103, 'Kolaborasi', 'Kolaborasi pemberian obat yang meningkatkan kepatenan jalan napas dan pertukaran gas.', 1);
