INSERT IGNORE INTO mst_siki (id, kode, label, tipe, definisi) VALUES (106, 'I.01018', 'Pencegahan Aspirasi', 'utama', '');
INSERT IGNORE INTO mst_siki (id, kode, label, tipe, definisi) VALUES (107, 'I.02038', 'Manajemen Defibrilasi', 'utama', '');
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Observasi', 'Periksa irama pada monitor setelah RJP 2 menit', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Lakukan resusitasi jantung paru (RJP) hingga mesin defibrillator siap', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Siapkan dan hidupkan mesin defibrillator', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Pasang monitor EKG', 3);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Pastikan irama EKG henti jantung (VF atau VT tanpa nadi)', 4);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Atur jumlah energi dengan metode asynchronized (360 joule untuk monofasik dan 120-200 joule untuk bifasik)', 5);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Angkat paddle dari mesin dan oleskan jeli pada paddle', 6);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Tempelkan paddle sternum (kanan) pada sisi kanan sternum di bawah klavikula dan paddle apeks (kiri) pada garis midaksilaris setinggi elektroda V6', 7);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Isi energi dengan menekan tombol charge pada paddle atau tombol charge pada mesin defibrillator dan menunggu hingga energi yang diinginkan tercapai', 8);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Hentikan RJP saat defibrillator siap', 9);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Teriak bahwa defibrillator telah siap (misal: “I’m clear, you’re clear, everybody’s clear”)', 10);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Berikan syok dengan menekan tombol pada kedua paddle bersamaan', 11);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Angkat paddle dan langsung lanjutkan RJP tanpa menunggu hasil irama yang muncul pada monitor setelah pemberian defibrilasi', 12);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (107, 'Terapeutik', 'Lanjutkan RJP sampai 2 menit', 13);
