INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (108, 'Terapeutik', 'Berikan infus cairan kristaloid 1-2 L pada dewasa', 2);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (108, 'Terapeutik', 'Berikan infus cairan kristaloid 20 mL/KgBB pada anak', 3);
