INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (120, 'Edukasi', 'Anjurkan melakukan fleksi dan ekstensi kaki paling sedikit 10 kali setiap jam', 1);
INSERT IGNORE INTO mst_siki_tindakan (id_siki, komponen, deskripsi, urutan) VALUES (120, 'Edukasi', 'Anjurkan melaporkan perdarahan yang berlebihan (mis: mimisan yang tidak biasa, muntah darah, urin berdarah, gusi berdarah, perdarahan pervaginam, perdarahan menstruasi yang berat, feses berdarah), nyeri atau bengkak yang tidak biasa, warna biru atau ungu pada jari kaki, nyeri di jari kaki, bisul atau bitnik putih di mulut atau tenggorokan.', 2);
